            </div>
            <div class="avatar-url">
                <label>Avatar URL</label>
                <input type="url" @bind="profileAvatarUrl" placeholder="https://example.com/avatar.png" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="profileName" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="profileEmail" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea rows="4" @bind="profileBio"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment NotificationsSection => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span class="toggle-switch"></span>
