            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfile();
                    break;
                case "Notifications":
                    notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    emailNotifications = notificationPrefs.EmailNotifications;
                    pushNotifications = notificationPrefs.PushNotifications;
                    weeklyDigest = notificationPrefs.WeeklyDigest;
                    mutedChannels = new List<string>(notificationPrefs.MutedChannels);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
                    showChangePassword = false;
                    currentPassword = "";
                    newPassword = "";
                    confirmPassword = "";
                    break;
                case "Appearance":
                    appearanceSettings = await SettingsService.GetAppearanceAsync();
                    theme = appearanceSettings.Theme;
                    fontSize = appearanceSettings.FontSize;
                    language = appearanceSettings.Language;
                    compactMode = appearanceSettings.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "error");
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ResetProfile()
    {
        if (savedProfile is null) return;
        profileName = savedProfile.DisplayName;
        profileEmail = savedProfile.Email;
        profileBio = savedProfile.Bio;
        profileAvatarUrl = savedProfile.AvatarUrl;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(profileName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfile();
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            showChangePassword = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to update password: {ex.Message}", "error");
        }
    }

    private void RequestRevokeSession(string sessionId)
    {
        confirmMessage = "Are you sure you want to revoke this session? The device will be signed out immediately.";
        confirmCallback = async () => await RevokeSession(sessionId);
        showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "success");
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Confirm dialog
    private async Task ConfirmAction()
    {
        showConfirmDialog = false;
        if (confirmCallback is not null)
            await confirmCallback();
    }

    private void CancelConfirm()
    {
        showConfirmDialog = false;
        confirmCallback = null;
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastCts?.Cancel();
        toastMessage = message;
        toastType = type;
        toastCts = new CancellationTokenSource();
        _ = AutoDismissToast(toastCts.Token);
    }

    private async Task AutoDismissToast(CancellationToken ct)
    {
        try
        {
            await Task.Delay(4000, ct);
            toastMessage = "";
            await InvokeAsync(StateHasChanged);
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        toastCts?.Cancel();
        toastMessage = "";
    }

    // Render fragments for each section
    private RenderFragment ProfileSection => __builder =>
    {
        <h2>Profile Settings</h2>

        <div class="avatar-section">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
            </div>
            <div class="avatar-url">
                <label>Avatar URL</label>
                <input type="url" @bind="profileAvatarUrl" placeholder="https://example.com/avatar.png" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="profileName" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="profileEmail" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea rows="4" @bind="profileBio"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment NotificationsSection => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>
            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>
        </div>

        <h3>Channel Muting</h3>
        <div class="channel-list">
            @foreach (var channel in AvailableChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted"
                           @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                    <span class="channel-name">#@channel</span>
                    @if (isMuted)
                    {
                        <span class="muted-badge">Muted</span>
                    }
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment SecuritySection => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="security-panel">
            <div class="panel-header" @onclick="() => showChangePassword = !showChangePassword">
                <h3>Change Password</h3>
                <span class="expand-icon">@(showChangePassword ? "▼" : "▶")</span>
            </div>
            @if (showChangePassword)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label>Current Password</label>
                        <input type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label>New Password</label>
                        <input type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label>Confirm New Password</label>
                        <input type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <label class="toggle-label">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span class="toggle-switch"></span>
                    Two-Factor Authentication
                </label>
                <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (securitySettings?.LastPasswordChange is not null)
            {
                <p class="last-changed">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions is { Count: > 0 })
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
                            var isFirst = session == securitySettings.Sessions[0];
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isFirst)
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (!isFirst)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p>No active sessions found.</p>
            }
        </div>
    };

    private RenderFragment AppearanceSection => __builder =>
    {
        <h2>Appearance Settings</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" checked="@(theme == "Light")"
                           @onchange='() => theme = "Light"' />
                    ☀️ Light
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" checked="@(theme == "Dark")"
                           @onchange='() => theme = "Dark"' />
                    🌙 Dark
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" checked="@(theme == "System")"
                           @onchange='() => theme = "System"' />
                    💻 System
                </label>
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" checked="@(fontSize == "Small")"
                           @onchange='() => fontSize = "Small"' />
                    Small
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" checked="@(fontSize == "Medium")"
                           @onchange='() => fontSize = "Medium"' />
                    Medium
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" checked="@(fontSize == "Large")"
                           @onchange='() => fontSize = "Large"' />
                    Large
                </label>
            </div>
        </div>

        <div class="form-group">
            <label>Language</label>
            <select @bind="language">
                @foreach (var lang in AvailableLanguages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="compactMode" />
                <span class="toggle-switch"></span>
                Compact Mode
            </label>
        </div>

        <div class="preview-area">
            <h3>Live Preview</h3>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-actions">
                    <button class="preview-btn">Button</button>
                    <span class="preview-link">Link</span>
                </div>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{fontSize.ToLowerInvariant()}");
        if (compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}
"}

