            <label>Language</label>
            <select @bind="language">
                @foreach (var lang in AvailableLanguages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="compactMode" />
                <span class="toggle-switch"></span>
                Compact Mode
            </label>
        </div>

        <div class="preview-area">
            <h3>Live Preview</h3>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-actions">
                    <button class="preview-btn">Button</button>
                    <span class="preview-link">Link</span>
                </div>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{fontSize.ToLowerInvariant()}");
        if (compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
